import * as z from "zod/v4";
import { emojiName } from "../../../channels/slack/agentic-signals.js";
import { defineTool } from "../../../tools.js";
const react = defineTool({
    description: [
        "Add an emoji reaction to a message in this thread.",
        "emoji is a Slack name without a leading colon, or :name:.",
        "ts is the message timestamp. Omit it to react to the thread root.",
        "The tool records nothing. The channel watching this turn adds the reaction.",
    ].join(" "),
    inputSchema: z.object({
        emoji: z
            .string()
            .trim()
            .min(1)
            .refine((value) => emojiName(value) !== undefined, "emoji must be a Slack reaction name"),
        ts: z.string().trim().min(1).optional(),
    }),
    execute: ({ emoji, ts }) => {
        const name = emojiName(emoji);
        if (name === undefined) {
            return "emoji must be a Slack reaction name";
        }
        return { emoji: name, ts };
    },
});
export default react;
